 11	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 12	pub enum ItemType {
 13	    Sword,
 14	    Amulet,
 15	    Staff,
 16	    Potion,
 17	    Rune,
 18	    Moonstone,
 19	}
 20	
 21	impl ItemType {
 22	    /// The MHPCO price-list row for a main item, or `None` for a component:
 23	    /// components are not on the main price list, they are charged per type
 24	    /// by `component_charge`.
 25	    fn main_item_base_premium(self) -> Option<f64> {
 26	        match self {
 27	            Self::Sword => Some(100.0),
 28	            Self::Amulet => Some(60.0),
 29	            Self::Staff => Some(80.0),
 30	            Self::Potion => Some(40.0),
 31	            Self::Rune | Self::Moonstone => None,
 32	        }
 33	    }
 34	
 35	    pub fn parse(name: &str) -> Result<Self, String> {
 36	        match name {
 37	            "sword" => Ok(Self::Sword),
 38	            "amulet" => Ok(Self::Amulet),
 39	            "staff" => Ok(Self::Staff),
 40	            "potion" => Ok(Self::Potion),
 41	            "rune" => Ok(Self::Rune),
 42	            "moonstone" => Ok(Self::Moonstone),
 43	            unknown => Err(format!("the MHPCO does not insure items of type '{unknown}'")),
 44	        }
 45	    }
 46	}
 47	
 48	pub struct Item {
 49	    item_type: ItemType,
 50	    cursed: bool,
 51	}
 52	
 53	impl Item {
 54	    pub fn new(item_type: ItemType) -> Self {
 55	        Self {
 56	            item_type,
 57	            cursed: false,
 58	        }
 59	    }
 60	
 61	    /// A cursed item carries the MHPCO's risk surcharge.
 62	    pub fn cursed(mut self) -> Self {
 63	        self.cursed = true;
 64	        self
 65	    }
 66	}
 67	
 68	const PROCESSING_FEE: u64 = 5;
 69	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
 70	/// Cursed items add a risk surcharge on their own base premium.
 71	const CURSE_SURCHARGE: f64 = 0.50;
 72	/// Components -- for example runes and moonstones -- share one price-list row.
 73	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
 74	
 75	/// Premiums are rounded up: the MHPCO's favour is the larger amount.
 76	fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
 77	    amount.ceil() as u64
 78	}
 79	
 80	/// Policy-wide modifiers apply to the policy base premium, the sum of all
 81	/// item base premiums. Every quoted item is treated as a first insurance.
 82	fn apply_policy_modifiers(_customer: &Customer, policy_base: f64) -> f64 {
 83	    policy_base + policy_base * FIRST_INSURANCE_SURCHARGE
 84	}
 85	
 86	/// A building block of exactly 3 alike components is offered at this price
 87	/// instead of the per-component base premium.
 88	const COMPONENT_BLOCK_SIZE: usize = 3;
 89	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
 90	
 91	/// Alike components -- components of the very same type -- are charged as a
 92	/// block when there are exactly 3 of them.
 93	const COMPONENT_TYPES: [ItemType; 2] = [ItemType::Rune, ItemType::Moonstone];
 94	
 95	fn component_charge(alike_count: usize) -> f64 {
 96	    if alike_count == COMPONENT_BLOCK_SIZE {
 97	        COMPONENT_BLOCK_BASE_PREMIUM
 98	    } else {
 99	        alike_count as f64 * COMPONENT_BASE_PREMIUM
100	    }
101	}
102	
103	/// How many of the policy's items are alike the given component type. Alike
104	/// components are the ones charged together, so this is where the MHPCO's
105	/// reading of "alike" lives.
106	fn alike_component_count(items: &[Item], component_type: ItemType) -> usize {
107	    items
108	        .iter()
109	        .filter(|item| item.item_type == component_type)
110	        .count()
111	}
112	
113	/// Main items are charged one price-list row each, individually.
114	fn main_items_base_premium(items: &[Item]) -> f64 {
115	    items
116	        .iter()
117	        .filter_map(|item| item.item_type.main_item_base_premium())
118	        .sum()
119	}
120	
121	/// Components are charged per group of alike components, so that a group of
122	/// exactly 3 earns the block price.
123	fn component_blocks_base_premium(items: &[Item]) -> f64 {
124	    COMPONENT_TYPES
125	        .iter()
126	        .map(|component_type| component_charge(alike_component_count(items, *component_type)))
127	        .sum()
128	}
129	
130	/// The policy base premium is the sum of the items' base premiums, with alike
131	/// components charged as blocks.
132	pub fn policy_base_premium(items: &[Item]) -> f64 {
133	    main_items_base_premium(items) + component_blocks_base_premium(items)
134	}
135	
136	/// Item-specific modifiers apply to the base premium of the affected item, not
137	/// to the policy total.
138	fn item_surcharges(items: &[Item]) -> f64 {
139	    items
140	        .iter()
141	        .map(|item| {
142	            let item_base = item.item_type.main_item_base_premium().unwrap_or(0.0);
143	            if item.cursed {
144	                item_base * CURSE_SURCHARGE
145	            } else {
146	                0.0
147	            }
148	        })
149	        .sum()
150	}
151	
152	pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
153	    let policy_base = policy_base_premium(items);
154	    let premium_before_fee =
155	        apply_policy_modifiers(customer, policy_base) + item_surcharges(items);
156	    round_premium_in_mhpco_favour(premium_before_fee) + PROCESSING_FEE
157	}
